"""Hosted read routes over existing native state and bounded artifacts."""

import json
import os
import re
import sys
from pathlib import Path

from fastapi import Depends, FastAPI, HTTPException
from fastapi.responses import FileResponse
from src.api.security import require_auth
from src.config.paths import get_runtime_root

_ID = re.compile(r"^[A-Za-z0-9_-]{1,128}$")
_SHADOW = re.compile(r"^shadow_[0-9a-f]{8}$")


def _private_file(path: Path) -> Path:
    try:
        resolved = path.resolve(strict=True)
        if path.is_symlink() or not resolved.is_file() or not resolved.is_relative_to(get_runtime_root().resolve()):
            raise ValueError("outside private state")
        return resolved
    except (ValueError, OSError) as exc:
        raise HTTPException(status_code=404, detail="Artifact not found") from exc


def register_mona_reads(app: FastAPI) -> None:
    if os.environ.get("VIBE_TRADING_HOSTED") != "1":
        return

    @app.get("/mona/sessions/{session_id}/attempts/{attempt_id}", dependencies=[Depends(require_auth)])
    async def get_attempt(session_id: str, attempt_id: str):
        if not _ID.fullmatch(session_id) or not _ID.fullmatch(attempt_id):
            raise HTTPException(status_code=404, detail="Attempt not found")
        host = sys.modules.get("api_server") or sys.modules.get("agent.api_server")
        service = host._get_session_service() if host is not None else None
        if service is None:
            raise HTTPException(status_code=503, detail="Session runtime unavailable")
        attempt = service.store.get_attempt(session_id, attempt_id)
        if attempt is None or attempt.session_id != session_id:
            raise HTTPException(status_code=404, detail="Attempt not found")
        data = attempt.to_dict()
        result = {key: data[key] for key in (
            "attempt_id", "session_id", "parent_attempt_id", "status", "summary", "error",
            "created_at", "started_at", "completed_at", "metrics",
        )}
        result["grounding_validation"] = None
        result["grounding_released"] = None
        if attempt.run_dir:
            try:
                path = _private_file(Path(attempt.run_dir) / "artifacts" / "grounding_evidence.json")
                if path.stat().st_size <= 16 * 1024 * 1024:
                    ledger = json.loads(path.read_text(encoding="utf-8"))
                    if not isinstance(ledger, dict):
                        raise ValueError("invalid grounding artifact")
                    validations = ledger.get("validations")
                    if isinstance(validations, list) and validations:
                        result["grounding_validation"] = validations[-1]
                    result["grounding_released"] = ledger.get("released")
            except (HTTPException, OSError, ValueError, TypeError):
                pass
        return result

    def profile(shadow_id: str):
        from src.shadow_account.storage import load_profile, profiles_dir

        if not _SHADOW.fullmatch(shadow_id):
            raise HTTPException(status_code=404, detail="Shadow profile not found")
        _private_file(profiles_dir() / f"{shadow_id}.json")
        try:
            return load_profile(shadow_id).to_dict()
        except (OSError, ValueError, KeyError, TypeError) as exc:
            raise HTTPException(status_code=422, detail="Shadow profile could not be read") from exc

    @app.get("/mona/shadow-profiles", dependencies=[Depends(require_auth)])
    async def list_profiles():
        from src.shadow_account.storage import profiles_dir

        items, unavailable = [], []
        for path in sorted(profiles_dir().glob("*.json")):
            if not _SHADOW.fullmatch(path.stem):
                continue
            try:
                items.append(profile(path.stem))
            except HTTPException:
                unavailable.append(path.stem)
        return {"profiles": items, "unavailable": unavailable}

    @app.get("/mona/shadow-profiles/{shadow_id}", dependencies=[Depends(require_auth)])
    async def get_profile(shadow_id: str):
        return profile(shadow_id)

    @app.get("/mona/artifacts/{kind}/{object_id}", dependencies=[Depends(require_auth)])
    async def get_artifact(kind: str, object_id: str):
        root = get_runtime_root()
        if not _ID.fullmatch(object_id):
            raise HTTPException(status_code=404, detail="Artifact not found")
        if kind in {"shadow-pdf", "shadow-html"}:
            if not _SHADOW.fullmatch(object_id):
                raise HTTPException(status_code=404, detail="Artifact not found")
            suffix = ".pdf" if kind == "shadow-pdf" else ".html"
            path = root / "shadow_reports" / (object_id + suffix)
        elif kind == "report-pdf":
            from src.tools.report_artifacts import report_path

            path = report_path(object_id)
            if path is None:
                raise HTTPException(status_code=404, detail="Artifact not found")
        else:
            names = {"run-config": "config.json", "run-code": "code/signal_engine.py",
                     "run-card": "run_card.json", "run-metrics": "artifacts/metrics.csv",
                     "run-trades": "artifacts/trades.csv", "run-equity": "artifacts/equity.csv"}
            if kind not in names:
                raise HTTPException(status_code=404, detail="Artifact not found")
            path = root / "runs" / object_id / names[kind]
        resolved = _private_file(path)
        return FileResponse(resolved, filename=resolved.name, content_disposition_type="attachment")
